import { createSlice } from '@reduxjs/toolkit';

const newsSlice = createSlice({
  name: 'news',
  initialState: [],
  reducers: {
    addNews: (state, action) => {
      // Add new news at the beginning
      state.unshift(action.payload);

      // Keep only the latest 10 news items
      if (state.length > 10) {
        state.splice(10);
      }
    },
    setNews: (state, action) => {
      // When setting initial news, keep only latest 10
      return action.payload.slice(0, 10);
    },
    clearOldNews: (state) => {
      // Optional method to manually clear old news
      return state.slice(0, 10);
    }
  }
});

export const { addNews, setNews } = newsSlice.actions;
export default newsSlice.reducer;
